// Makes src/data/static/legalTexts.ts from the drafts in ../legal/ (KAN-62), so the app can show them offline.
// Run after changing a file in legal/:   npm run legal:texts
// CI checks the generated file is up to date.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const legal = join(here, '..', '..', 'legal');
const out = join(here, '..', 'src', 'data', 'static', 'legalTexts.ts');

const files = {
  privacy: 'privacy-policy.md',
  terms: 'terms.md',
  entryRules: 'entry-rules-disclaimer.md',
};

const body = Object.entries(files)
  .map(
    ([key, file]) =>
      `  ${key}: ${JSON.stringify(readFileSync(join(legal, file), 'utf8').replace(/\r\n/g, '\n'))},`,
  )
  .join('\n');

writeFileSync(
  out,
  `// Generated by scripts/make-legal-texts.mjs from ../legal/*.md. Do not edit: change the .md file and run
// npm run legal:texts.
export const legalTexts = {
${body}
} as const;

export type LegalDoc = keyof typeof legalTexts;
`,
);
console.log('Wrote', out);
